// ─────────────────────────────────────────────────────────────
// Format Error Message
// Builds a readable Telegram message from the error payload
// that n8n's Error Trigger provides automatically
// ─────────────────────────────────────────────────────────────

const err = $input.first().json;

// Extract the useful parts from n8n's error payload
const workflowName = err.workflow?.name ?? 'Unknown workflow';
const lastNode     = err.execution?.lastNodeExecuted ?? 'Unknown node';
const errorMessage = err.execution?.error?.message ?? 'No error message';
const errorType    = err.execution?.error?.name ?? 'UnknownError';
const executionId  = err.execution?.id ?? 'N/A';
const timestamp    = new Date().toISOString();

const message = `⚠️ WORKFLOW FAILURE

Workflow: ${workflowName}
Failed node: ${lastNode}
Error type: ${errorType}
Message: ${errorMessage}
Execution ID: ${executionId}
Time: ${timestamp}

Check n8n at http://localhost:5678 for details.`;

return [{
  json: {
    error_message: message,
    telegram_chat_id: YOUR_TELEGRAM_CHAT_ID
  }
}];
